reference_solution:
def number_of_weak_characters(properties):
    properties.sort(key=lambda item:(-item[0],item[1]))
    strongest_defense=-1
    answer=0
    for attack,defense in properties:
        if defense<strongest_defense:
            answer+=1
        strongest_defense=max(strongest_defense,defense)
    return answer

